// VIP Pharmacy BACKEND - English messages + backup + safe shutdown
// Usage (inside the Pharmacy-Store folder):  node english-backend.js
// This script only updates files. Any file it overwrites is first copied to the "_update_backup" folder.
 import fs from "fs";
 import path from "path";

const NAME = 'vip-pharmacy-backend';
let ROOT = null;
const here = process.cwd();
try { if (JSON.parse(fs.readFileSync(path.join(here, 'package.json'), 'utf8')).name === NAME) ROOT = here; } catch (e) {}
if (!ROOT && fs.existsSync(path.join(here, NAME, 'package.json'))) ROOT = path.join(here, NAME);
if (!ROOT) { console.log('ERROR: folder "' + NAME + '" was not found. Run this script from the folder that contains ' + NAME + ' (Pharmacy-Store).'); process.exit(1); }

const FILES = {"backup.bat": "QGVjaG8gb2ZmCmNhbGwgbnBtIHJ1biBiYWNrdXAKcGF1c2UK", "prisma/seed.ts": "", "src/middleware.ts": "", "src/config.ts": "", "src/server.ts": "", "src/stock.ts": "", "src/app.ts": "", "src/routes/settings.ts": "", "src/routes/catalog.ts": "", "src/routes/finance.ts": "", "src/routes/pos.ts": "", "src/routes/auth.ts": "", "src/routes/partners.ts": "", "src/routes/store.ts": "", "src/routes/inventory.ts": "", "src/routes/reports.ts": "", "scripts/backup.js": ""};
const stamp = new Date().toISOString().replace(/[:T]/g, '-').slice(0, 16);
const bak = path.join(ROOT, '_update_backup', stamp);
let written = 0, backedUp = 0;
for (const [rel, b64] of Object.entries(FILES)) {
  const full = path.join(ROOT, rel);
  const data = Buffer.from(b64, 'base64');
  if (fs.existsSync(full)) {
    if (fs.readFileSync(full).equals(data)) continue; // pehle se same
    const b = path.join(bak, rel);
    fs.mkdirSync(path.dirname(b), { recursive: true });
    fs.copyFileSync(full, b);
    backedUp++;
  }
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, data);
  written++;
}

const APPENDS = [{"path": ".gitignore", "marker": "backups", "text": "backups\n_update_backup\n"}];
for (const a of APPENDS) {
  const full = path.join(ROOT, a.path);
  const cur = fs.existsSync(full) ? fs.readFileSync(full, 'utf8') : '';
  if (cur.includes(a.marker)) continue;
  fs.writeFileSync(full, cur + (cur.endsWith('\n') || !cur ? '' : '\n') + a.text);
  written++;
}

try {
  const pj = path.join(ROOT, 'package.json');
  const j = JSON.parse(fs.readFileSync(pj, 'utf8'));
  if (!j.scripts.backup) { j.scripts.backup = 'node scripts/backup.js'; fs.writeFileSync(pj, JSON.stringify(j, null, 2) + '\n'); console.log('Added "npm run backup" to package.json.'); }
} catch (e) { console.log('package.json was not updated:', e.message); }

console.log('Update complete: ' + written + ' files written/updated, ' + backedUp + ' old files backed up to ' + bak);
console.log('Done. Run:  npm run backup   (take your first backup). The server restarts by itself.');
